                c.drag(&mut gb, &Gesture::new(pts).pressure(0.55, 0.0).ramps(0.05, 0.85).shake(0.5), None);
            }
        }
        c.dry();
    }

    o.end(&mut c, &mut rng);
    c.relief(st.relief.0, st.relief.1);
    o.save(&mut c);
}

